import React, { useState } from "react";
import { Form, Button, Card, Row, Col } from "react-bootstrap";
import { useNavigate } from "react-router-dom";

function PlanScreen() {
  const [month, setMonth] = useState("");
  const [city, setCity] = useState("");
  const [functions, setFunctions] = useState("1");
  const [showPlan, setShowPlan] = useState(false);

  const navigate = useNavigate();

  const steps = [
  { title: "Book venue", link: "/?keyword=Halls&page=1" },
  { title: "Book photographer", link: "/?keyword=Photographers&page=1" },
  { title: "Makeup artist", link: "/?keyword=Makeup_Artist&page=1" },
  { title: "Decorator", link: "/?keyword=Decorators&page=1" },
  { title: "Catering", link: "/?keyword=Caterers&page=1" },
];


  const submitHandler = (e) => {
    e.preventDefault();
    setShowPlan(true);
  };

  return (
    <>
      <h3 className="mb-3">Plan your wedding in 2 minutes</h3>

      {!showPlan && (
        <Card className="p-3">
          <Form onSubmit={submitHandler}>

            <Form.Group className="mb-3">
              <Form.Label>Wedding month</Form.Label>
              <Form.Control
                type="month"
                value={month}
                onChange={(e) => setMonth(e.target.value)}
                required
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>City</Form.Label>
              <Form.Control
                type="text"
                placeholder="Enter your city"
                value={city}
                onChange={(e) => setCity(e.target.value)}
                required
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Number of functions</Form.Label>
              <Form.Select
                value={functions}
                onChange={(e) => setFunctions(e.target.value)}
              >
                <option value="1">1</option>
                <option value="2">2</option>
                <option value="3">3 or more</option>
              </Form.Select>
            </Form.Group>

            <Button type="submit">Generate my plan</Button>
          </Form>
        </Card>
      )}

      {showPlan && (
        <div className="mt-4">
          <h5>Your simple wedding plan</h5>

          <Row>
            {steps.map((step, i) => (
              <Col md={6} key={i} className="mb-3">
                <Card className="p-3">
                  <strong>{step.title}</strong>
                  <Button
                    variant="outline-primary"
                    className="mt-2"
                    onClick={() => navigate(step.link)}
                  >
                    Book appointment
                  </Button>
                </Card>
              </Col>
            ))}
          </Row>
        </div>
      )}
    </>
  );
}

export default PlanScreen;
