// src/components/ProductCarousel.jsx
import React, { useState, useEffect, useRef } from 'react';
import api from '../utils/api';
import { Link } from 'react-router-dom';
import { Carousel } from 'react-bootstrap';
import Loader from './Loader';
import Message from './Message';

function ProductCarousel() {
  const [products, setProducts]     = useState([]);
  const [loading, setLoading]       = useState(false);
  const [error, setError]           = useState('');
  const [windowWidth, setWindowWidth] = useState(window.innerWidth);
  const [hoveredId, setHoveredId]   = useState(null);
  const [activeIndex, setActiveIndex] = useState(0);

  useEffect(() => {
    const fetchTopProducts = async () => {
      try {
        setLoading(true);
        const { data } = await api.get('/api/products/all/top/');
        setProducts(data);
      } catch (err) {
        setError(
          err.response && err.response.data.detail
            ? err.response.data.detail
            : err.message
        );
      } finally {
        setLoading(false);
      }
    };
    fetchTopProducts();

    const handleResize = () => setWindowWidth(window.innerWidth);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const filteredProducts = products.filter(
    p => p.image !== '/images/placeholder.png'
  );

  const itemsPerSlide = windowWidth < 576 ? 1 : windowWidth < 992 ? 2 : 4;

  const slides = [];
  for (let i = 0; i < filteredProducts.length; i += itemsPerSlide) {
    slides.push(filteredProducts.slice(i, i + itemsPerSlide));
  }

  return (
    <div style={styles.section}>
      {/* Decorative star pattern overlay */}
      <div style={styles.bgPattern} aria-hidden="true" />

      {/* Gold top border accent */}
      <div style={styles.topAccent} />

      <div style={styles.header}>
        <span style={styles.eyebrow}>✦ Featured Vendors ✦</span>
        <h2 style={styles.title}>Top-Rated Wedding Services</h2>
        <div style={styles.divider}>
          <div style={styles.dividerLine} />
          <span style={styles.dividerDiamond}>◆</span>
          <div style={styles.dividerLine} />
        </div>
      </div>

      {loading ? (
        <div style={{ padding: '2rem' }}><Loader /></div>
      ) : error ? (
        <div style={{ padding: '1rem 2rem' }}><Message variant="danger">{error}</Message></div>
      ) : (
        <div style={styles.carouselWrapper}>
          <Carousel
            pause="hover"
            activeIndex={activeIndex}
            onSelect={setActiveIndex}
            interval={3800}
            indicators={slides.length > 1}
            prevIcon={<span style={styles.navIcon}>‹</span>}
            nextIcon={<span style={styles.navIcon}>›</span>}
          >
            {slides.map((slide, index) => (
              <Carousel.Item key={index}>
                <div style={styles.slide}>
                  {slide.map((product, i) => (
                    <Link
                      key={product._id}
                      to={`/product/${product._id}`}
                      style={styles.card}
                      onMouseEnter={() => setHoveredId(product._id)}
                      onMouseLeave={() => setHoveredId(null)}
                    >
                      {/* Image container */}
                      <div style={styles.imgContainer}>
                        <img
                          src={product.image}
                          alt={product.name}
                          style={{
                            ...styles.img,
                            transform: hoveredId === product._id ? 'scale(1.08)' : 'scale(1)',
                          }}
                        />
                        {/* Gold shimmer overlay on hover */}
                        <div style={{
                          ...styles.imgOverlay,
                          opacity: hoveredId === product._id ? 1 : 0,
                        }} />
                        {/* Category badge */}
                        {product.category && (
                          <span style={styles.badge}>
                            {product.category.replace(/_/g, ' ')}
                          </span>
                        )}
                      </div>

                      {/* Card body */}
                      <div style={{
                        ...styles.cardBody,
                        background: hoveredId === product._id
                          ? 'linear-gradient(135deg, #3d0d28 0%, #5e143f 100%)'
                          : '#fff',
                      }}>
                        <h4 style={{
                          ...styles.cardTitle,
                          color: hoveredId === product._id ? '#fff' : '#3d0d28',
                        }}>
                          {product.name}
                        </h4>
                        {product.area_name && (
                          <p style={{
                            ...styles.cardArea,
                            color: hoveredId === product._id ? 'rgba(255,255,255,0.65)' : '#9a7a85',
                          }}>
                            📍 {product.area_name}
                          </p>
                        )}
                        <div style={styles.cardFooter}>
                          {product.rating > 0 && (
                            <span style={styles.rating}>
                              {'★'.repeat(Math.round(product.rating))}
                              <span style={styles.ratingNum}> {Number(product.rating).toFixed(1)}</span>
                            </span>
                          )}
                          <span style={{
                            ...styles.viewBtn,
                            background: hoveredId === product._id ? '#c9973a' : '#5e143f',
                            color: hoveredId === product._id ? '#3d0d28' : '#fff',
                          }}>
                            View →
                          </span>
                        </div>
                      </div>
                    </Link>
                  ))}
                </div>
              </Carousel.Item>
            ))}
          </Carousel>

          {/* Slide counter dots */}
          {slides.length > 1 && (
            <div style={styles.dotRow}>
              {slides.map((_, i) => (
                <button
                  key={i}
                  onClick={() => setActiveIndex(i)}
                  style={{
                    ...styles.dot,
                    background: i === activeIndex ? '#c9973a' : 'rgba(255,255,255,0.3)',
                    width: i === activeIndex ? '24px' : '8px',
                  }}
                  aria-label={`Go to slide ${i + 1}`}
                />
              ))}
            </div>
          )}
        </div>
      )}

      {/* Gold bottom border accent */}
      <div style={styles.bottomAccent} />
    </div>
  );
}

/* ── Styles ─────────────────────────────────────────────── */
const styles = {
  section: {
    position: 'relative',
    background: 'linear-gradient(155deg, #3d0d28 0%, #5e143f 55%, #7a1a50 100%)',
    padding: '3rem 0 2rem',
    overflow: 'hidden',
  },
  bgPattern: {
    position: 'absolute',
    inset: 0,
    backgroundImage: `url("data:image/svg+xml,%3Csvg width='72' height='72' viewBox='0 0 72 72' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23f0c96a' fill-opacity='0.05'%3E%3Cpath d='M36 4l5 10 11 1.5-8 7.8 1.9 11L36 29l-9.9 5.3L28 23.3 20 15.5 31 14z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E")`,
    pointerEvents: 'none',
  },
  topAccent: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    height: '3px',
    background: 'linear-gradient(90deg, transparent, #c9973a 30%, #f0c96a 50%, #c9973a 70%, transparent)',
  },
  bottomAccent: {
    position: 'absolute',
    bottom: 0,
    left: 0,
    right: 0,
    height: '3px',
    background: 'linear-gradient(90deg, transparent, #c9973a 30%, #f0c96a 50%, #c9973a 70%, transparent)',
  },
  header: {
    textAlign: 'center',
    marginBottom: '2rem',
    position: 'relative',
    zIndex: 1,
  },
  eyebrow: {
    display: 'inline-block',
    fontFamily: "'DM Sans', 'Open Sans', sans-serif",
    fontSize: '0.72rem',
    fontWeight: 500,
    letterSpacing: '0.2em',
    textTransform: 'uppercase',
    color: '#f0c96a',
    opacity: 0.85,
    marginBottom: '0.4rem',
  },
  title: {
    fontFamily: "'Cormorant Garamond', 'Georgia', serif",
    fontSize: 'clamp(1.6rem, 3vw, 2.4rem)',
    fontWeight: 600,
    color: '#fff',
    margin: '0.2rem 0 0.8rem',
    letterSpacing: '-0.01em',
    lineHeight: 1.2,
  },
  divider: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '10px',
  },
  dividerLine: {
    width: '60px',
    height: '1px',
    background: 'linear-gradient(90deg, transparent, #c9973a)',
  },
  dividerDiamond: {
    color: '#c9973a',
    fontSize: '0.65rem',
  },
  carouselWrapper: {
    position: 'relative',
    zIndex: 1,
    padding: '0 1rem',
  },
  slide: {
    display: 'flex',
    justifyContent: 'center',
    gap: '16px',
    padding: '0.5rem 1.5rem 1.5rem',
  },
  card: {
    flex: '1 1 0',
    minWidth: 0,
    maxWidth: '260px',
    borderRadius: '14px',
    overflow: 'hidden',
    textDecoration: 'none',
    display: 'flex',
    flexDirection: 'column',
    boxShadow: '0 8px 32px rgba(0,0,0,0.35)',
    transition: 'transform 0.28s cubic-bezier(0.4,0,0.2,1), box-shadow 0.28s ease',
    cursor: 'pointer',
    transform: 'translateY(0)',
  },
  imgContainer: {
    position: 'relative',
    overflow: 'hidden',
    height: '190px',
    background: '#1a0a0f',
  },
  img: {
    width: '100%',
    height: '100%',
    objectFit: 'cover',
    objectPosition: 'top',
    display: 'block',
    transition: 'transform 0.45s cubic-bezier(0.4,0,0.2,1)',
  },
  imgOverlay: {
    position: 'absolute',
    inset: 0,
    background: 'linear-gradient(160deg, rgba(201,151,58,0.18) 0%, rgba(94,20,63,0.45) 100%)',
    transition: 'opacity 0.3s ease',
    pointerEvents: 'none',
  },
  badge: {
    position: 'absolute',
    top: '10px',
    left: '10px',
    background: 'rgba(201,151,58,0.92)',
    color: '#3d0d28',
    fontFamily: "'DM Sans', sans-serif",
    fontSize: '0.68rem',
    fontWeight: 600,
    letterSpacing: '0.06em',
    textTransform: 'uppercase',
    padding: '3px 10px',
    borderRadius: '999px',
    backdropFilter: 'blur(4px)',
  },
  cardBody: {
    padding: '0.85rem 1rem 1rem',
    transition: 'background 0.28s ease',
  },
  cardTitle: {
    fontFamily: "'Cormorant Garamond', Georgia, serif",
    fontSize: '1.05rem',
    fontWeight: 600,
    margin: '0 0 4px',
    lineHeight: 1.3,
    transition: 'color 0.28s ease',
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
  cardArea: {
    fontFamily: "'DM Sans', sans-serif",
    fontSize: '0.78rem',
    margin: '0 0 8px',
    transition: 'color 0.28s ease',
    whiteSpace: 'nowrap',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
  cardFooter: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginTop: '4px',
  },
  rating: {
    color: '#c9973a',
    fontSize: '0.82rem',
    fontWeight: 600,
    letterSpacing: '0.05em',
  },
  ratingNum: {
    color: '#9a7a85',
    fontWeight: 400,
    fontSize: '0.78rem',
  },
  viewBtn: {
    display: 'inline-block',
    fontSize: '0.75rem',
    fontWeight: 600,
    fontFamily: "'DM Sans', sans-serif",
    letterSpacing: '0.06em',
    padding: '4px 12px',
    borderRadius: '999px',
    transition: 'background 0.28s ease, color 0.28s ease',
    textDecoration: 'none',
  },
  navIcon: {
    fontSize: '2.2rem',
    color: '#f0c96a',
    fontFamily: 'Georgia, serif',
    lineHeight: 1,
    textShadow: '0 2px 8px rgba(0,0,0,0.5)',
    userSelect: 'none',
  },
  dotRow: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    gap: '6px',
    marginTop: '1rem',
    padding: '0 0 0.5rem',
  },
  dot: {
    height: '8px',
    borderRadius: '999px',
    border: 'none',
    padding: 0,
    cursor: 'pointer',
    transition: 'all 0.3s ease',
  },
};

export default ProductCarousel;